usage.code:
rgi main -i anno/${SAMPLE}.faa -o res/${SAMPLE}_rgi_loose -t protein \
  --include_loose --local -n ${THREADS}
# 报告中必须区分 strict 与 loose，不要混在一起统计

recipes.bash:
rgi main -i 03_annotation/${SAMPLE}.faa -o 04_resistance/${SAMPLE}_rgi \
  -t protein --local --clean -n ${THREADS}

# 抽取 Strict 命中：**不要硬编码列号**。RGI 的列序随版本变化，写死 $6
# 会在版本不同时静默产出「只有表头、没有数据行」的结果。按表头名定位：
awk -F'\t' 'NR==1 { for (i=1; i<=NF; i++) if ($i=="Cut_Off") col=i;
                  if (!col) { print "未找到 Cut_Off 列，请检查表头" > "/dev/stderr"; exit 1 }
                  print; next }
             $col=="Strict"' 04_resistance/${SAMPLE}_rgi.txt \
  > 09_results/${SAMPLE}.rgi_strict.tsv
[ -s 09_results/${SAMPLE}.rgi_strict.tsv ] || echo "警告：Strict 命中为空，先确认 Cut_Off 取值是否写对" >&2

